// شبكة أمان: لو صار خطأ JavaScript في أي شاشة، نوريه بوضوح بدل ما التطبيق
// يختفي بصمت (وده كان يبان للمستخدم كإنه "رجعه لتسجيل الدخول")
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  render() {
    if (this.state.error) {
      return (
        <div style={{ padding: 24, fontFamily: "sans-serif", direction: "rtl", background: "#fff", color: "#c00" }}>
          <h2>حصل خطأ في هذه الشاشة</h2>
          <pre style={{ whiteSpace: "pre-wrap", fontSize: 13, background: "#fee", padding: 12, borderRadius: 8 }}>
            {this.state.error.message}
            {"\n\n"}
            {this.state.error.stack}
          </pre>
          <button onClick={() => this.setState({ error: null })} style={{ marginTop: 12, padding: "8px 16px" }}>
            حاول تاني
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

function JomlaAdminAppInner() {
  const { actor, loading, requestOtp, verifyOtp, logout, can } = useSession("employee");
  // مكدّس تنقّل كامل (زي تاريخ المتصفح) بدل خريطة "رجوع" ثابتة — كل عنصر فيه
  // شاشة (view) + بيانات مختارة (sel) في تلك اللحظة بالضبط، عشان سهم الرجوع
  // يرجّعك لنفس الشاشة والتبويب اللي كنت فيه، مش يبدأ من الأول دايمًا
  const [stack, setStack] = useState([{ view: "dashboard", sel: {} }]);
  const { view, sel } = stack[stack.length - 1];

  // يدخل شاشة جديدة فوق المكدّس (يحافظ على اللي قبلها عشان الرجوع)
  const go = (v, patch = {}) => {
    setStack((s) => [...s, { view: v, sel: { ...s[s.length - 1].sel, ...patch } }]);
  };
  // يرجع خطوة وحدة بالمكدّس — لنفس الشاشة اللي كنت فيها بالضبط
  const goBack = () => {
    setStack((s) => (s.length > 1 ? s.slice(0, -1) : s));
  };
  // يحدّث بيانات الشاشة الحالية بالمكدّس بدون ما يفتح شاشة جديدة — نستخدمها عشان
  // نحفظ أي تبويب/فلتر فرعي (زي تبويب "كشف المخزون" أو نص البحث) وقت ما يتغيّر،
  // عشان لو دخلنا لتفاصيل صنف مثلًا وبعدين رجعنا، نلقى نفس التبويب والفلتر بالضبط
  const patchSel = (patch) => {
    setStack((s) => {
      const copy = s.slice();
      const last = copy[copy.length - 1];
      copy[copy.length - 1] = { ...last, sel: { ...last.sel, ...patch } };
      return copy;
    });
  };
  // تنقّل من القائمة الجانبية: بداية جديدة من قسم رئيسي، يصفّر المكدّس
  const navRoot = (v) => setStack([{ view: v, sel: {} }]);

  if (loading) return <Shell><Centered><Loader2 className="spin" size={26} /><p>جارٍ التحميل…</p></Centered></Shell>;
  if (!actor) return <Shell><LoginView onRequestOtp={requestOtp} onVerify={verifyOtp} /></Shell>;

  const ROOTS = ["dashboard", "orders", "catalog", "accounts", "employees", "delivery", "operations", "settings", "reports", "auditLog"];
  const TITLES = {
    dashboard: "نظرة عامة", orders: "الطلبيات", catalog: "إدارة الأصناف", accounts: "الحسابات",
    employees: "الموظفون والرواتب", delivery: "التوصيل والمندوبين",
    operations: "الأصول والمتابعة", settings: "الإعدادات", reports: "التقارير العامة",
    auditLog: "سجل التدقيق",
    orderDetail: "تفاصيل الطلبية", customerLedger: "كشف حساب العميل",
    supplierLedger: "كشف حساب المورد", itemDetail: "بطاقة الصنف",
    supplierStockLog: "حركة أصناف المورد", driverLedger: "كشف حركة المندوب",
  };
  // تُستخدم فقط لتمييز أي قسم رئيسي مفعّل في القائمة الجانبية وانت داخل شاشة فرعية منه —
  // الرجوع الفعلي توا يمشي بالمكدّس (goBack)، مو بهذي الخريطة
  const backTo = {
    orderDetail: "orders", customerLedger: "reports",
    supplierLedger: "reports", itemDetail: "reports", supplierStockLog: "reports",
    driverLedger: "reports",
  };

  return (
    <Shell wide>
      <div className="app-shell">
        <Sidebar view={view} roots={ROOTS} backTo={backTo} onNav={navRoot} onLogout={logout} />
        <div className="app-content">
          <header className="content-header">
            {!ROOTS.includes(view) && (
              <button className="header-back" onClick={goBack}>
                <ArrowRight size={16} /> رجوع
              </button>
            )}
            <h1>{TITLES[view]}</h1>
            <span className="header-actor">{actor.name}</span>
          </header>

          <main className="content-body">
            {view === "dashboard" && <Dashboard onGo={go} />}
            {view === "orders" && <OrdersHub onOpen={(id) => go("orderDetail", { orderId: id })} initialTab={sel.ordersTab} onPatch={patchSel} />}
            {view === "orderDetail" && <OrderDetail orderId={sel.orderId} can={can} onDone={goBack} />}
            {view === "catalog" && <CatalogManagerView can={can} />}
            {view === "accounts" && <AccountsView can={can} />}
            {view === "employees" && <EmployeesView can={can} onGo={go} />}
            {view === "delivery" && <DeliveryView can={can} />}
            {view === "operations" && <OperationsView can={can} />}
            {view === "settings" && <SettingsView can={can} />}
            {view === "reports" && <ReportsView onGo={go} sel={sel} onPatch={patchSel} />}
            {view === "auditLog" && <ErrorBoundary><AuditLogView can={can} /></ErrorBoundary>}
            {view === "customerLedger" && <LedgerView kind="customer" id={sel.accountId} name={sel.partyName} />}
            {view === "supplierLedger" && <LedgerView kind="supplier" id={sel.accountId} name={sel.partyName} />}
            {view === "supplierStockLog" && <SupplierStockLog id={sel.accountId} name={sel.partyName} />}
            {view === "driverLedger" && <DriverLedgerView id={sel.accountId} name={sel.partyName} />}
            {view === "itemDetail" && <ItemDetail productId={sel.productId} can={can} />}
          </main>
        </div>
      </div>
    </Shell>
  );
}

export default function JomlaAdminApp() {
  return (
    <ErrorBoundary>
      <JomlaAdminAppInner />
    </ErrorBoundary>
  );
}

