// تحقق وتوحيد رقم الهاتف الليبي: 10 خانات تبدأ بـ 09 (يقبل +218 و 218 وبدون الصفر)
function normalizeLibyanPhone(raw) {
  let d = String(raw || "").replace(/[٠-٩]/g, (c) => "٠١٢٣٤٥٦٧٨٩".indexOf(c)).replace(/\D/g, "");
  if (d.startsWith("00218")) d = d.slice(5);
  else if (d.startsWith("218")) d = d.slice(3);
  if (/^9\d{8}$/.test(d)) d = "0" + d;
  return d;
}
function phoneError(raw) {
  const d = normalizeLibyanPhone(raw);
  if (!d) return "اكتب رقم الهاتف";
  if (d.length > 10) return "الرقم غير صحيح، الرجاء التأكد من الرقم وإعادة المحاولة";
  if (d.length < 10) return "الرقم ناقص، الرجاء تعديل الرقم";
  if (!/^09\d{8}$/.test(d)) return "الرقم غير صحيح، الرجاء التأكد من الرقم وإعادة المحاولة";
  return "";
}

function LoginView({ onRequestOtp, onVerify }) {
  const [step, setStep] = useState("phone");
  const [phone, setPhone] = useState("");
  const [phoneErr, setPhoneErr] = useState("");
  const lastTried = useRef("");
  const [digits, setDigits] = useState(["", "", "", ""]);
  const [seconds, setSeconds] = useState(0);
  const refs = useRef([]);
  const send = useAction(onRequestOtp);
  const verify = useAction(onVerify);

  useEffect(() => {
    if (step !== "otp" || seconds <= 0) return;
    const t = setTimeout(() => setSeconds((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [step, seconds]);
  useEffect(() => { if (step === "otp") refs.current[0]?.focus(); }, [step]);
  async function handleSend() {
    const err = phoneError(phone);
    if (err) { setPhoneErr(err); return; }
    setPhoneErr("");
    try {
      await send.run(normalizeLibyanPhone(phone));
    } catch {
      return; // رسالة الخطأ (مثلاً: غير مسجل) تظهر تحت الحقل، ونبقى في شاشة الهاتف
    }
    lastTried.current = "";
    setDigits(["", "", "", ""]);
    setSeconds(30);
    setStep("otp");
  }

  // تعبئة خانات الرمز: كتابة رقم، أو لصق الرمز كامل (من الرسالة أو التعبئة التلقائية)
  function fillDigits(start, text) {
    const nums = String(text || "").replace(/[٠-٩]/g, (c) => "٠١٢٣٤٥٦٧٨٩".indexOf(c)).replace(/\D/g, "");
    const next = [...digits];
    if (!nums) { next[start] = ""; setDigits(next); return; }
    if (nums.length <= 2) {
      next[start] = nums.slice(-1);
      setDigits(next);
      if (start < 3) refs.current[start + 1]?.focus();
      return;
    }
    const from = nums.length >= 4 ? 0 : start;
    for (let k = 0; k < nums.length && from + k < 4; k++) next[from + k] = nums[k];
    setDigits(next);
    refs.current[Math.min(from + nums.length, 4) - 1]?.focus();
  }

  // أول ما تتعبى الخانات الأربعة يدخل مباشرة بدون ضغط زر
  useEffect(() => {
    const code = digits.join("");
    if (step !== "otp" || code.length < 4 || verify.pending || lastTried.current === code) return;
    lastTried.current = code;
    verify.run(normalizeLibyanPhone(phone), code).catch(() => {
      setDigits(["", "", "", ""]);
      lastTried.current = "";
      refs.current[0]?.focus();
    });
  }, [digits, step]);

  return (
    <div className="login-screen">
      <LogoIntro width={250} />
      <p className="login-sub">لوحة الإدارة — منصة جملة لتجارة الجملة</p>

      {step === "phone" ? (
        <div className="login-card">
          <label className="field-label">رقم حساب الإدارة</label>
          <input className="field-input" placeholder="09XXXXXXXX" value={phone} dir="ltr"
            style={{ textAlign: "right" }} inputMode="numeric"
            onChange={(e) => { setPhone(e.target.value); setPhoneErr(""); }}
            onKeyDown={(e) => e.key === "Enter" && handleSend()} />
          {(phoneErr || send.error) && <p className="field-error">{phoneErr || send.error}</p>}
          <button className="btn-primary" onClick={handleSend} disabled={send.pending}>
            {send.pending ? "جارٍ الإرسال…" : "إرسال رمز التحقق"}
          </button>
          <p className="login-note">{COMPANY.address}</p>
        </div>
      ) : (
        <div className="login-card">
          <label className="field-label">رمز التحقق المُرسل إلى {phone}</label>
          <div className="otp-row" dir="ltr">
            {digits.map((d, i) => (
              <input key={i} ref={(el) => (refs.current[i] = el)} className="otp-box" value={d}
                type="tel" inputMode="numeric"
                autoComplete={i === 0 ? "one-time-code" : "off"}
                onChange={(e) => fillDigits(i, e.target.value)}
                onPaste={(e) => { e.preventDefault(); fillDigits(0, e.clipboardData.getData("text")); }}
                onFocus={(e) => e.target.select()}
                onKeyDown={(e) => e.key === "Backspace" && !digits[i] && i > 0 && refs.current[i - 1]?.focus()} />
            ))}
          </div>
          {verify.error && <p className="field-error">{verify.error}</p>}
          <button className="btn-primary" disabled={verify.pending || digits.join("").length < 4}
            onClick={() => verify.run(normalizeLibyanPhone(phone), digits.join("")).catch(() => {})}>
            {verify.pending ? "جارٍ التحقق…" : "تأكيد الدخول"}
          </button>
          <div className="otp-footer">
            <button className="link-btn" onClick={() => { setStep("phone"); setDigits(["", "", "", ""]); }}>تعديل الرقم</button>
            <button className="link-btn" disabled={seconds > 0} onClick={handleSend}>
              {seconds > 0 ? `إعادة الإرسال بعد ${seconds} ث` : "إعادة إرسال الرمز"}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

