/* كشف البحث — ما بحث عنه العملاء (يساعد في معرفة الأصناف المطلوبة وغير الموجودة) */
function SearchLogView() {
  // الافتراضي آخر 30 يوم (مثل السابق). بدون فترة = أقصى مدة يدعمها الخادم (365 يوم)
  const [range, setRange] = useState(() => RANGE_CHIPS_DAYS[1].get());
  const [onlyEmpty, setOnlyEmpty] = useState(false);
  const [q, setQ] = useState("");
  const { data, loading, error, reload } = useFetch(
    (s) => api.searchLogAdmin({ days: 365, ...rangeParams(range), onlyEmpty, q }, s), [range.from, range.to, onlyEmpty, q]
  );
  const rows = data?.rows ?? [];
  const totals = data?.totals ?? {};

  return (
    <div>
      <div className="toolbar-row">
        <div className="chip-row">
          <button className={"chip" + (onlyEmpty ? " chip-active" : "")} onClick={() => setOnlyEmpty((v) => !v)}>بدون نتائج فقط</button>
        </div>
        <SearchBar inline value={q} onChange={setQ} placeholder="ابحث في الكلمات..." />
      </div>
      <DateRangeBar value={range} onChange={setRange} chips={RANGE_CHIPS_DAYS.slice(0, 3)} />
      {!range.from && !range.to && <p className="hint">بدون فترة محددة: يعرض آخر 365 يوم (أقصى مدة يدعمها الخادم).</p>}

      <div className="stat-grid">
        <Stat label="إجمالي عمليات البحث" value={Number(totals.searches ?? 0)} />
        <Stat label="كلمات مختلفة" value={Number(totals.distinctQueries ?? 0)} />
        <Stat label="كلمات بدون نتائج" value={Number(totals.zeroResultQueries ?? 0)} debt={Number(totals.zeroResultQueries ?? 0) > 0} />
      </div>

      {loading ? <Spinner />
       : error ? <ErrorState message={error} onRetry={reload} />
       : !rows.length ? <Empty icon={Search} text="لا توجد عمليات بحث مسجّلة في هذه الفترة. هذا الكشف يسجّل كلمات البحث التي يكتبها العملاء في تطبيقهم، لتعرف ماذا يطلبون وما غير الموجود عندكم." />
       : (
        <table className="data-table">
          <thead><tr>
            <th>الكلمة</th><th>عدد المرات</th><th>عدد العملاء</th><th>آخر نتائج</th><th>آخر بحث</th>
          </tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.normalized}>
                <td>{r.sample || r.normalized}</td>
                <td className="cell-amount">{r.searches}</td>
                <td className="cell-muted">{r.customers}</td>
                <td className={Number(r.lastResults) === 0 ? "cell-debt" : "cell-muted"}>
                  {Number(r.lastResults) === 0 ? <b>غير موجود</b> : r.lastResults}
                </td>
                <td className="cell-muted">{day(r.lastAt)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

function CatalogProductsPane({ can, onChanged }) {
  const [groupBy, setGroupBy] = useState("supplier"); // supplier | section
  const [supplierId, setSupplierId] = useState("");
  const [sectionId, setSectionId] = useState("");
  const [search, setSearch] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [showBulkImages, setShowBulkImages] = useState(false);
  const [showExport, setShowExport] = useState(false);
  const [selected, setSelected] = useState({}); // الأصناف المعلّمة (id → الصنف) وتبقى حتى لو غيّرت الفلتر
  const suppliers = useFetch(() => api.suppliers(), []);
  const sections = useFetch(() => api.sections({ flat: 1 }), []);
  const products = useFetch(
    (s) => api.products({ supplierId: supplierId || undefined, sectionId: sectionId || undefined, search: search || undefined }, s),
    [supplierId, sectionId, search]
  );
  // قائمة منفصلة بأصناف المورد المختار بدون فلتر القسم، بس لمعرفة أي الأقسام فعلًا عنده فيها أصناف
  const supplierProducts = useFetch(
    (s) => api.products({ supplierId }, s),
    [supplierId],
    { skip: !supplierId }
  );

  // الأقسام اللي فيها فعلًا أصناف للمورد المختار (لو محدد مورد)، وإلا كل الأقسام اللي فيها أصناف بشكل عام
  const relevantSectionIds = supplierId
    ? new Set((supplierProducts.data ?? []).map((p) => p.section_id))
    : null;
  const sectionOptions = (sections.data ?? []).filter((s) => !relevantSectionIds || relevantSectionIds.has(s.id));

  // التجميع: حسب المورد (والأصناف داخله مرتبة بالقسم ثم الاسم) أو حسب القسم (والأصناف داخله مرتبة بالاسم ثم المورد)
  const ar = (a, b) => String(a || "").localeCompare(String(b || ""), "ar");
  const grouped = [];
  const byKey = {};
  for (const p of products.data ?? []) {
    const key = groupBy === "section" ? p.section_id : p.supplier_id;
    if (!byKey[key]) {
      byKey[key] = { supplierId: key, supplierName: groupBy === "section" ? p.section_name : p.supplier_name, items: [] };
      grouped.push(byKey[key]);
    }
    byKey[key].items.push(p);
  }
  grouped.sort((a, b) => ar(a.supplierName, b.supplierName));
  for (const g of grouped) {
    g.items.sort(groupBy === "section"
      ? (a, b) => ar(a.name, b.name) || ar(a.supplier_name, b.supplier_name)
      : (a, b) => ar(a.section_name, b.section_name) || ar(a.name, b.name));
  }

  return (
    <div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12, alignItems: "center" }}>
        <select className="field-input" style={{ maxWidth: 220 }} value={supplierId} onChange={(e) => { setSupplierId(e.target.value); setSectionId(""); }}>
          <option value="">كل الموردين</option>
          {(suppliers.data ?? []).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
        </select>
        <select className="field-input" style={{ maxWidth: 220 }} value={sectionId} onChange={(e) => setSectionId(e.target.value)}>
          <option value="">كل الأقسام</option>
          {sectionOptions.map((s) => {
            const parent = s.parent_id ? (sections.data ?? []).find((x) => x.id === s.parent_id) : null;
            return <option key={s.id} value={s.id}>{parent ? `${parent.name} ← ${s.name}` : s.name}</option>;
          })}
        </select>
        <SearchBar value={search} onChange={setSearch} placeholder="ابحث بالاسم أو المورد أو كود الصنف..." inline />
        {can("catalog.manage") && (
          <button className="chip chip-add" onClick={() => setShowAdd((v) => !v)}>
            <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> {showAdd ? "إلغاء" : "إضافة صنف جديد"}
          </button>
        )}
        {can("catalog.manage") && (
          <button className="chip" onClick={() => setShowBulkImages((v) => !v)}>
            <ImageIcon size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> {showBulkImages ? "إلغاء" : "رفع صور دفعة واحدة"}
          </button>
        )}
        <div className="chip-row" style={{ margin: 0 }}>
          <button className={"chip" + (groupBy === "supplier" ? " chip-active" : "")} onClick={() => setGroupBy("supplier")}>ترتيب حسب المورد</button>
          <button className={"chip" + (groupBy === "section" ? " chip-active" : "")} onClick={() => setGroupBy("section")}>ترتيب حسب القسم</button>
        </div>
        {(can("catalog.manage") || can("reports.view")) && (
          <button className="chip" onClick={() => setShowExport((v) => !v)}>
            <Download size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> {showExport ? "إغلاق التصدير" : "تصدير المخزون إلى Excel"}
          </button>
        )}
      </div>

      {showExport && (
        <InventoryExportPanel
          shown={products.data ?? []} selected={selected} onClearSelected={() => setSelected({})}
          supplierName={(suppliers.data ?? []).find((x) => x.id === supplierId)?.name}
          sectionName={(sections.data ?? []).find((x) => x.id === sectionId)?.name}
        />
      )}

      {showAdd && (
        <AdminAddProductForm onClose={() => setShowAdd(false)}
          onCreated={() => { setShowAdd(false); products.reload(); onChanged?.(); }} />
      )}

      {showBulkImages && (
        <AdminBulkImagesModal suppliers={suppliers.data ?? []} onClose={() => setShowBulkImages(false)} onDone={products.reload} />
      )}

      {products.loading ? <Spinner /> : products.error ? <ErrorState message={products.error} onRetry={products.reload} /> : (
        !grouped.length ? <div className="center-state"><Package size={22} /><p>لا توجد أصناف مطابقة</p></div> : (
          grouped.map((g) => (
            <div key={g.supplierId} className="invoice-block" style={{ marginBottom: 16 }}>
              <div className="invoice-head">
                <span>{groupBy === "section" ? `القسم: ${g.supplierName}` : g.supplierName}</span>
                <span className="invoice-head-count">{g.items.length} صنف</span>
              </div>
              <table className="data-table" style={{ marginBottom: 0 }}>
                <thead><tr>
                  <th style={{ width: 28 }}>
                    <input type="checkbox" title="تعليم كل أصناف هذا المورد"
                      checked={g.items.length > 0 && g.items.every((p) => selected[p.id])}
                      onChange={(e) => setSelected((cur) => {
                        const next = { ...cur };
                        for (const p of g.items) { if (e.target.checked) next[p.id] = p; else delete next[p.id]; }
                        return next;
                      })} />
                  </th>
                  <th>صورة</th><th>الصنف</th><th>الأنواع</th><th>كود الصنف</th><th>القسم</th><th>السعر</th><th>الكمية</th><th></th>
                </tr></thead>
                <tbody>
                  {g.items.map((p) => (
                    <CatalogProductRow key={p.id} product={p} can={can} onDone={() => { products.reload(); onChanged?.(); }}
                      showSupplier={groupBy === "section"}
                      checked={!!selected[p.id]}
                      onCheck={(on) => setSelected((cur) => {
                        const next = { ...cur };
                        if (on) next[p.id] = p; else delete next[p.id];
                        return next;
                      })} />
                  ))}
                </tbody>
              </table>
            </div>
          ))
        )
      )}
    </div>
  );
}

function CatalogProductRow({ product: p, can, onDone, checked, onCheck, showSupplier }) {
  const [editing, setEditing] = useState(false);
  const [showVariants, setShowVariants] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [sku, setSku] = useState(p.supplier_sku || "");
  const selectable = !!onCheck;
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [name, setName] = useState(p.name);
  const [price, setPrice] = useState(p.base_price);
  const [sectionId, setSectionId] = useState(p.section_id);
  const [imageUrl, setImageUrl] = useState(p.image_url || "");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);
  const sections = useFetch(() => api.sections({ flat: 1 }), [], { skip: !editing });

  const save = useAction(() => api.updateProduct(p.id, {
    name: name.trim() !== p.name ? name.trim() : undefined,
    basePrice: Number(price) !== Number(p.base_price) ? Number(price) : undefined,
    sectionId: sectionId !== p.section_id ? sectionId : undefined,
    imageUrl: imageUrl !== (p.image_url || "") ? imageUrl : undefined,
    supplierSku: sku.trim() && sku.trim() !== (p.supplier_sku || "") ? sku.trim() : undefined,
  }));
  const toggle = useAction(() => api.updateProduct(p.id, { isActive: !(p.is_active !== false) }));
  const remove = useAction(() => api.deleteProduct(p.id));

  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    api.uploadImage(file).then((res) => setImageUrl(res.url)).catch(() => {}).finally(() => setUploading(false));
  }

  if (!editing) {
    return (
      <>
        <tr style={p.variants?.length > 0 ? { background: "rgba(34,197,94,.07)" } : undefined}>
          {selectable && <td><input type="checkbox" checked={!!checked} onChange={(e) => onCheck(e.target.checked)} /></td>}
          <td>
            {p.image_url
              ? <img src={p.image_url} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }} />
              : <div style={{ width: 40, height: 40, borderRadius: 8, background: "var(--paper)", display: "flex",
                  alignItems: "center", justifyContent: "center", color: "var(--ink-soft)" }}><ImageIcon size={16} /></div>}
          </td>
          <td className="cell-id">
            {p.name}
            {p.approval_status === "pending" && <span className="status-pill" style={{ marginRight: 6 }}>بانتظار الموافقة</span>}
            {p.is_active === false && <span className="status-pill" style={{ marginRight: 6 }}>موقوف</span>}
            {showSupplier && <div className="cell-muted" style={{ fontSize: 12 }}>المورد: {p.supplier_name}</div>}
          </td>
          <td>
            {p.variants?.length > 0
              ? <span className="status-pill status-pill-approved">{p.variants.length} أنواع</span>
              : <span className="cell-muted">—</span>}
          </td>
          <td className="cell-muted" dir="ltr" style={{ textAlign: "right" }}>
            {p.variants?.length > 0 ? <span dir="rtl">حسب النوع</span> : (p.supplier_sku || "—")}
          </td>
          <td className="cell-muted">{p.section_name}</td>
          <td>{money(p.base_price)}</td>
          <td className="cell-muted">{p.stock_qty}</td>
          <td style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            <button className="invoice-action-btn" onClick={() => setEditing(true)}>تعديل</button>
            <button className="invoice-action-btn" onClick={() => setShowVariants((v) => !v)}>الأنواع</button>
            <button className="invoice-action-btn" onClick={() => setShowHistory((v) => !v)}>{showHistory ? "إغلاق السجل" : "السجل"}</button>
            {can("accounts.sections") && (
              <button className="invoice-action-btn" disabled={toggle.pending} onClick={() => toggle.run().then(onDone).catch(() => {})}>
                {p.is_active !== false ? "إيقاف" : "تفعيل"}
              </button>
            )}
            {can("catalog.delete") && (
              confirmingDelete ? (
                <button className="invoice-action-btn" disabled={remove.pending}
                  onClick={() => remove.run().then(onDone).catch(() => {})}>تأكيد الحذف</button>
              ) : (
                <button className="invoice-action-btn" onClick={() => setConfirmingDelete(true)}>حذف</button>
              )
            )}
          </td>
        </tr>
        {showVariants && (
          <tr><td colSpan={selectable ? 9 : 8} style={{ background: "var(--paper)" }}>
            <AdminVariantsManager product={p} />
          </td></tr>
        )}
        {showHistory && (
          <tr><td colSpan={selectable ? 9 : 8} style={{ background: "var(--paper)" }}>
            <ProductHistoryPanel productId={p.id} />
          </td></tr>
        )}
      </>
    );
  }

  return (
    <tr>
      {selectable && <td></td>}
      <td>
        {imageUrl
          ? <img src={imageUrl} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }} />
          : <div style={{ width: 40, height: 40, borderRadius: 8, background: "var(--paper)" }} />}
        <button className="link-btn" disabled={uploading} onClick={() => fileRef.current?.click()} style={{ display: "block", fontSize: 11 }}>
          {uploading ? "…" : "تغيير"}
        </button>
        <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
      </td>
      <td>
        <input className="field-input" value={name} onChange={(e) => setName(e.target.value)} />
      </td>
      <td>
        {p.variants?.length > 0
          ? <span className="status-pill status-pill-approved">{p.variants.length} أنواع</span>
          : <span className="cell-muted">—</span>}
      </td>
      <td>
        {p.variants?.length > 0
          ? <span className="cell-muted">الكود على كل نوع</span>
          : <input className="field-input" dir="ltr" placeholder="كود الصنف" value={sku} onChange={(e) => setSku(e.target.value)} />}
      </td>
      <td>
        <select className="field-input" value={sectionId} onChange={(e) => setSectionId(e.target.value)}>
          {(sections.data ?? []).map((s) => {
            const parent = s.parent_id ? (sections.data ?? []).find((x) => x.id === s.parent_id) : null;
            return <option key={s.id} value={s.id}>{parent ? `${parent.name} ← ${s.name}` : s.name}</option>;
          })}
        </select>
      </td>
      <td><input className="field-input" type="number" min="0" step="0.05" value={price} onChange={(e) => setPrice(e.target.value)} /></td>
      <td className="cell-muted">{p.stock_qty}</td>
      <td style={{ display: "flex", gap: 6 }}>
        <button className="invoice-action-btn" disabled={save.pending}
          onClick={() => save.run().then(() => { onDone(); setEditing(false); }).catch(() => {})}>حفظ</button>
        <button className="btn-ghost" onClick={() => setEditing(false)}>إلغاء</button>
        {save.error && <p className="field-error">{save.error}</p>}
      </td>
    </tr>
  );
}

// سجل الصنف: حركات المخزون + كل التعديل — لكل تغيير: من (الاسم + النوع) ومتى وأي حقل وقبل ← بعد
function HistoryThumb({ url }) {
  if (!url) return <span className="cell-muted">بدون صورة</span>;
  return (
    <a href={url} target="_blank" rel="noreferrer" style={{ display: "inline-block", verticalAlign: "middle" }}>
      <img src={url} alt="" loading="lazy"
        style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 6, border: "1px solid var(--rule, #ddd)" }} />
    </a>
  );
}

function ProductHistoryPanel({ productId }) {
  const { data, loading, error, reload } = useFetch(() => api.productHistory(productId), [productId]);
  const when = (at) => {
    try { return new Date(at).toLocaleString("en-GB", { dateStyle: "short", timeStyle: "short" }); } catch { return day(at); }
  };
  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;
  const items = data?.items ?? [];
  const approvalRow = (it) => it.action === "product.resubmitted" || it.action === "product.updated_resubmitted";
  return (
    <div style={{ padding: "10px 8px" }}>
      <p className="hint">سجل «{data?.product?.name}» — كل تغيير: من قام به، ومتى، وقيمته قبل وبعد.</p>
      {!items.length ? <p className="cell-muted">لا توجد حركات أو تعديلات مسجّلة بعد</p> : (
        <div className="ledger-list">
          {items.map((it) => (
            <div className="ledger-row" key={it.id} style={{ display: "block", padding: "8px 0", borderTop: "1px solid var(--rule, #e5e5e5)" }}>
              <div style={{ display: "flex", justifyContent: "space-between", gap: 8, flexWrap: "wrap" }}>
                <b style={approvalRow(it) || it.action === "product.rejected" ? { color: "var(--warn, #b45309)" } : undefined}>
                  {it.title}{it.variant_label ? ` — ${it.variant_label}` : ""}
                </b>
                <span className="cell-muted">
                  {when(it.at)} · من: {it.actor_name || "—"}{it.actor_type_label ? ` (${it.actor_type_label})` : ""}
                </span>
              </div>
              {it.qty_change != null && (
                <div>
                  <span className={it.qty_change >= 0 ? "cell-amount" : "cell-amount cell-debt"}>
                    {it.qty_change >= 0 ? "+" : ""}{it.qty_change}
                  </span>
                  {it.reason && <span className="cell-muted"> — {it.reason}</span>}
                </div>
              )}
              {it.qty_change == null && it.reason && <div className="cell-muted">السبب: {it.reason}</div>}
              {it.changes?.map((c, i) => (
                c.type === "image" ? (
                  <div key={i} className="cell-muted" style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginTop: 4 }}>
                    <span>من: {it.actor_name || "—"} — تغيير الصورة — قبل:</span>
                    <HistoryThumb url={c.from} />
                    <span>←  بعد:</span>
                    <HistoryThumb url={c.to} />
                  </div>
                ) : (
                  <div key={i} className="cell-muted">
                    {c.label} — من: {it.actor_name || "—"} — قبل: <span style={{ textDecoration: "line-through" }}>{c.from}</span>
                    {" ← "}بعد: <b style={{ color: "var(--ink)" }}>{c.to}</b>
                  </div>
                )
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// تصدير المخزون إلى Excel: كل المخزون، أو حسب الفلتر الحالي (مورد/قسم/بحث)، أو الأصناف المعلّمة بـ ✓
function InventoryExportPanel({ shown, selected, onClearSelected, supplierName, sectionName }) {
  const selectedList = Object.values(selected);
  const [mode, setMode] = useState(selectedList.length ? "selected" : "filtered");
  const run = useAction(async () => {
    let list;
    if (mode === "all") list = await api.products({ limit: 5000 });
    else if (mode === "selected") list = selectedList;
    else list = shown;
    if (!list?.length) throw new Error("ما في أصناف للتصدير بالاختيار هذا");
    const rows = list.flatMap((p) => {
      const base = {
        "المورد": p.supplier_name, "القسم": p.section_name, "اسم الصنف": p.name,
      };
      const state = p.is_active === false ? "موقوف" : p.approval_status === "pending" ? "بانتظار الموافقة" : "نشط";
      if (p.variants?.length) {
        return p.variants.map((v) => ({
          ...base, "النوع": v.label, "الكود": v.sku || "", "وحدة البيع": p.unit,
          "السعر (د.ل)": Number(v.price), "الكمية": Number(v.stockQty), "الحالة": state,
        }));
      }
      return [{
        ...base, "النوع": "", "الكود": p.supplier_sku || "", "وحدة البيع": p.unit,
        "السعر (د.ل)": Number(p.base_price), "الكمية": Number(p.stock_qty), "الحالة": state,
      }];
    });
    const XLSX = await import("xlsx");
    const ws = XLSX.utils.json_to_sheet(rows);
    ws["!cols"] = [{ wch: 20 }, { wch: 18 }, { wch: 30 }, { wch: 18 }, { wch: 16 }, { wch: 14 }, { wch: 12 }, { wch: 10 }, { wch: 14 }];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "المخزون");
    XLSX.writeFile(wb, `مخزون-${new Date().toISOString().slice(0, 10)}.xlsx`);
    return rows.length;
  });
  const filterDesc = [supplierName && `المورد: ${supplierName}`, sectionName && `القسم: ${sectionName}`].filter(Boolean).join(" · ");

  return (
    <div className="detail-card" style={{ marginBottom: 16 }}>
      <h2 className="subsection-heading">تصدير المخزون إلى Excel</h2>
      <label style={{ display: "block", margin: "6px 0" }}>
        <input type="radio" checked={mode === "all"} onChange={() => setMode("all")} /> كل المخزون (كل الموردين وكل الأقسام)
      </label>
      <label style={{ display: "block", margin: "6px 0" }}>
        <input type="radio" checked={mode === "filtered"} onChange={() => setMode("filtered")} /> حسب الفلتر الحالي ({shown.length} صنف){filterDesc ? ` — ${filterDesc}` : " — اختر مورد أو قسم من فوق لتحديد النتيجة"}
      </label>
      <label style={{ display: "block", margin: "6px 0" }}>
        <input type="radio" checked={mode === "selected"} onChange={() => setMode("selected")} /> الأصناف المعلّمة ✓ ({selectedList.length}) — علّم بالمربعات في الجدول
        {selectedList.length > 0 && <button className="link-btn" style={{ marginRight: 8 }} onClick={onClearSelected}>مسح التعليم</button>}
      </label>
      {run.error && <p className="field-error">{run.error}</p>}
      <button className="btn-primary" disabled={run.pending || (mode === "selected" && !selectedList.length)}
        onClick={() => run.run().catch(() => {})}>
        {run.pending ? "جارٍ التجهيز…" : "تصدير"}
      </button>
      <p className="hint">الصنف اللي له أنواع يطلع سطر لكل نوع بكوده وسعره وكميته.</p>
    </div>
  );
}

function AdminVariantsManager({ product }) {
  const { data, loading, error, reload } = useFetch(() => api.productVariants(product.id), [product.id]);
  const [showAdd, setShowAdd] = useState(false);

  return (
    <div style={{ padding: "10px 8px" }}>
      <p className="hint">أنواع «{product.name}» — كل نوع له سعره وكمية مخزونه الخاصين.</p>
      {loading ? <Spinner /> : error ? <ErrorState message={error} onRetry={reload} /> : (
        !data?.length ? <p className="cell-muted">لا توجد أنواع بعد</p> : (
          <table className="data-table" style={{ marginTop: 0 }}>
            <thead><tr><th>النوع</th><th>الكود</th><th>السعر</th><th>الكمية</th><th>الحالة</th><th></th></tr></thead>
            <tbody>{data.map((v) => <AdminVariantRow key={v.id} variant={v} onDone={reload} />)}</tbody>
          </table>
        )
      )}
      {showAdd ? (
        <AdminAddVariantForm productId={product.id} onClose={() => setShowAdd(false)} onCreated={() => { reload(); setShowAdd(false); }} />
      ) : (
        <button className="chip chip-add" style={{ marginTop: 8 }} onClick={() => setShowAdd(true)}>
          <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> إضافة نوع
        </button>
      )}
    </div>
  );
}

function AdminVariantRow({ variant: v, onDone }) {
  const [label, setLabel] = useState(v.label);
  const [sku, setSku] = useState(v.sku || "");
  const [price, setPrice] = useState(v.price);
  const [adjusting, setAdjusting] = useState(false);
  const [delta, setDelta] = useState("");
  const [reason, setReason] = useState("");
  const save = useAction(() => api.updateProductVariant(v.id, {
    label: label.trim() !== v.label ? label.trim() : undefined,
    sku: sku.trim() && sku.trim() !== (v.sku || "") ? sku.trim() : undefined,
    price: Number(price) !== Number(v.price) ? Number(price) : undefined,
  }));
  const adjust = useAction(() => api.adjustVariantStock(v.id, { changeQty: Number(delta), reason: reason.trim() }));
  const toggle = useAction(() => api.updateProductVariant(v.id, { isActive: !v.is_active }));
  const remove = useAction(() => api.deleteProductVariant(v.id));
  const dirty = label.trim() !== v.label || (sku.trim() && sku.trim() !== (v.sku || "")) || Number(price) !== Number(v.price);
  const canAdjust = Number(delta) !== 0 && !Number.isNaN(Number(delta)) && reason.trim().length >= 2;

  return (
    <>
      <tr>
        <td><input className="field-input" style={{ marginBottom: 0, minWidth: 90 }} value={label} onChange={(e) => setLabel(e.target.value)} /></td>
        <td><input className="field-input" style={{ marginBottom: 0, minWidth: 80 }} dir="ltr" placeholder="الكود" value={sku} onChange={(e) => setSku(e.target.value)} /></td>
        <td><input type="number" min="0" step="0.05" className="qty-input" style={{ width: 80 }} value={price} onChange={(e) => setPrice(e.target.value)} /></td>
        <td>
          <b>{v.stock_qty}</b>
          <button className="link-btn" style={{ marginRight: 6, fontSize: 12 }} onClick={() => setAdjusting((x) => !x)}>
            {adjusting ? "إلغاء" : "تعديل الكمية"}
          </button>
        </td>
        <td><span className={"status-pill" + (v.is_active ? " status-pill-approved" : "")}>{v.is_active ? "مفعّل" : "موقوف"}</span></td>
        <td style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
          {dirty && (
            <button className="save-inline" disabled={save.pending} onClick={() => save.run().then(onDone).catch(() => {})}>
              {save.pending ? "…" : <Check size={13} />}
            </button>
          )}
          <button className="invoice-action-btn" disabled={toggle.pending} onClick={() => toggle.run().then(onDone).catch(() => {})}>
            {v.is_active ? "إيقاف" : "تفعيل"}
          </button>
          <button className="invoice-action-btn" disabled={remove.pending}
            onClick={() => { if (window.confirm(`حذف النوع "${v.label}"؟`)) remove.run().then(onDone).catch(() => {}); }}>حذف</button>
        </td>
      </tr>
      {adjusting && (
        <tr>
          <td colSpan={6} style={{ background: "var(--paper)" }}>
            <p className="hint" style={{ margin: "4px 0" }}>الكمية الحالية {v.stock_qty}. اكتب الزيادة بـ (+) أو الخصم بـ (−) مع السبب، وتتسجل في السجل باسمك.</p>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
              <input className="field-input" style={{ marginBottom: 0, maxWidth: 120 }} type="number" placeholder="مثال: 5 أو -3"
                value={delta} onChange={(e) => setDelta(e.target.value)} />
              <input className="field-input" style={{ marginBottom: 0, flex: 1, minWidth: 160 }} placeholder="السبب (مثال: جرد، بضاعة جديدة)"
                value={reason} onChange={(e) => setReason(e.target.value)} />
              <button className="invoice-action-btn" disabled={!canAdjust || adjust.pending}
                onClick={() => adjust.run().then(() => { setAdjusting(false); setDelta(""); setReason(""); onDone(); }).catch(() => {})}>
                {adjust.pending ? "…" : `حفظ (الكمية بعد: ${Number(v.stock_qty) + (Number(delta) || 0)})`}
              </button>
            </div>
            {adjust.error && <p className="field-error">{adjust.error}</p>}
          </td>
        </tr>
      )}
      {(save.error || toggle.error || remove.error) && (
        <tr><td colSpan={6}><p className="field-error">{save.error || toggle.error || remove.error}</p></td></tr>
      )}
    </>
  );
}

function AdminAddVariantForm({ productId, onClose, onCreated }) {
  const [label, setLabel] = useState("");
  const [price, setPrice] = useState("");
  const [stockQty, setStockQty] = useState("0");
  const [sku, setSku] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);
  const create = useAction(() => api.createProductVariant(productId, {
    label: label.trim(), price: Number(price), stockQty: Number(stockQty) || 0,
    sku: sku.trim() || undefined, imageUrl: imageUrl || undefined,
  }));
  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    api.uploadImage(file).then((res) => setImageUrl(res.url)).catch(() => {}).finally(() => setUploading(false));
  }
  const valid = label.trim() && Number(price) > 0 && sku.trim();

  return (
    <div style={{ marginTop: 10 }}>
      <label className="field-label">اسم النوع (مثال: أحمر - وسط - كرتونة)</label>
      <input className="field-input" value={label} onChange={(e) => setLabel(e.target.value)} />
      <label className="field-label">السعر (د.ل)</label>
      <input className="field-input" type="number" min="0" step="0.05" value={price} onChange={(e) => setPrice(e.target.value)} />
      <label className="field-label">الكمية المتوفرة</label>
      <input className="field-input" type="number" min="0" value={stockQty} onChange={(e) => setStockQty(e.target.value)} />
      <label className="field-label">كود النوع عند المورد (إجباري) + صورة</label>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
        <input className="field-input" style={{ marginBottom: 0, flex: 1 }} value={sku} onChange={(e) => setSku(e.target.value)} dir="ltr" />
        {imageUrl
          ? <img src={imageUrl} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }} onClick={() => setImageUrl("")} title="اضغط للإزالة" />
          : <button type="button" className="btn-ghost" style={{ width: "auto" }} disabled={uploading} onClick={() => fileRef.current?.click()}>
              {uploading ? "…" : "📷 صورة"}
            </button>}
        <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
      </div>
      {create.error && <p className="field-error">{create.error}</p>}
      <div className="add-form-actions">
        <button className="btn-primary" disabled={!valid || create.pending || uploading}
          onClick={() => create.run().then(onCreated).catch(() => {})}>
          {create.pending ? "جارٍ الحفظ…" : "حفظ النوع"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

function AdminBulkImagesModal({ suppliers, onClose, onDone }) {
  const [supplierId, setSupplierId] = useState("");
  const [files, setFiles] = useState([]);
  const upload = useAction(() => api.uploadProductImagesBulk(files, supplierId));
  const [result, setResult] = useState(null);
  const fileRef = useRef(null);

  return (
    <div className="detail-card voucher-form" style={{ marginBottom: 16 }}>
      <h2 className="subsection-heading">رفع صور الأصناف دفعة واحدة</h2>
      <p className="hint">
        سمّ كل صورة برقم الصنف عند المورد (supplier_sku) بالضبط، مثلاً <code dir="ltr">SKU123.jpg</code> تنحط
        تلقائيًا على الصنف اللي رقمه SKU123 عند المورد المحدد تحت.
      </p>
      <label className="field-label">المورد</label>
      <select className="field-input" value={supplierId} onChange={(e) => setSupplierId(e.target.value)}>
        <option value="">اختر المورد</option>
        {suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
      </select>

      <button type="button" className="btn-ghost" style={{ marginTop: 8 }} onClick={() => fileRef.current?.click()}>
        اختر الصور ({files.length})
      </button>
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" multiple
        style={{ display: "none" }} onChange={(e) => setFiles([...(e.target.files || [])])} />

      {upload.error && <p className="field-error">{upload.error}</p>}

      {result && (
        <div style={{ marginTop: 10 }}>
          <p className="hint">تم مطابقة {result.matched.length} صورة، وتعذّرت مطابقة {result.unmatched.length}.</p>
          {result.unmatched.length > 0 && (
            <ul style={{ fontSize: 13, color: "#a12626" }}>
              {result.unmatched.map((u, i) => <li key={i}>{u.file} — {u.reason}</li>)}
            </ul>
          )}
        </div>
      )}

      <div className="add-form-actions">
        <button className="btn-primary" disabled={!supplierId || !files.length || upload.pending}
          onClick={() => upload.run().then((res) => { setResult(res); onDone(); }).catch(() => {})}>
          {upload.pending ? "جارٍ الرفع…" : "رفع ومطابقة"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إغلاق</button>
      </div>
    </div>
  );
}

// منشئ الأنواع (ألوان/مقاسات/عبوات) داخل نموذج إضافة الصنف نفسه — كل نوع سطر: الاسم، السعر، الكمية، كود المورد، صورة
function VariantsBuilder({ value, onChange }) {
  const setRow = (i, patch) => onChange(value.map((r, idx) => (idx === i ? { ...r, ...patch } : r)));
  const addRow = () => onChange([...value, { label: "", price: "", stockQty: "", sku: "", imageUrl: "" }]);
  const removeRow = (i) => onChange(value.filter((_, idx) => idx !== i));
  const [uploadingIdx, setUploadingIdx] = useState(null);

  function pickImage(i, e) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;
    setUploadingIdx(i);
    api.uploadImage(file)
      .then((res) => setRow(i, { imageUrl: res.url }))
      .catch(() => {})
      .finally(() => setUploadingIdx(null));
  }

  const total = value.reduce((s, r) => s + (Number(r.stockQty) || 0), 0);

  return (
    <div style={{ marginBottom: 12 }}>
      {value.map((r, i) => (
        <div key={i} className="detail-card" style={{ padding: 10, marginBottom: 8 }}>
          <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 6 }}>
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} placeholder="النوع (مثال: أحمر - وسط)"
              value={r.label} onChange={(e) => setRow(i, { label: e.target.value })} />
            <button type="button" className="link-btn" onClick={() => removeRow(i)}>حذف</button>
          </div>
          <div style={{ display: "flex", gap: 8, marginBottom: 6 }}>
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} type="number" min="0" step="0.05" placeholder="السعر"
              value={r.price} onChange={(e) => setRow(i, { price: e.target.value })} />
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} type="number" min="0" placeholder="الكمية"
              value={r.stockQty} onChange={(e) => setRow(i, { stockQty: e.target.value })} />
          </div>
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <input className="field-input" style={{ marginBottom: 0, flex: 1 }} dir="ltr" placeholder="كود النوع (إجباري)"
              value={r.sku} onChange={(e) => setRow(i, { sku: e.target.value })} />
            {r.imageUrl
              ? <img src={r.imageUrl} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }}
                  onClick={() => setRow(i, { imageUrl: "" })} title="اضغط للإزالة" />
              : (
                <label className="btn-ghost" style={{ width: "auto", cursor: "pointer", margin: 0 }}>
                  {uploadingIdx === i ? "…" : "📷 صورة"}
                  <input type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={(e) => pickImage(i, e)} />
                </label>
              )}
          </div>
        </div>
      ))}
      <button type="button" className="chip chip-add" onClick={addRow}>+ إضافة نوع</button>
      {value.length > 0 && <p className="hint" style={{ marginTop: 6 }}>إجمالي كمية الصنف = مجموع الأنواع: <b>{total}</b></p>}
    </div>
  );
}

function AdminAddProductForm({ onClose, onCreated }) {
  const suppliers = useFetch(() => api.suppliers(), []);
  const [form, setForm] = useState({
    supplierId: "", sectionId: "", name: "", unit: "", basePrice: "", stockQty: "0", supplierSku: "",
  });
  const sections = useFetch(
    () => (form.supplierId ? api.sections({ flat: 1, supplierId: form.supplierId }) : Promise.resolve([])),
    [form.supplierId]
  );
  const [imageUrl, setImageUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const fileRef = useRef(null);
  const [createdProduct, setCreatedProduct] = useState(null);
  const [hasVariants, setHasVariants] = useState(false);
  const [variants, setVariants] = useState([{ label: "", price: "", stockQty: "", sku: "", imageUrl: "" }]);
  const variantsValid = !hasVariants || (variants.length > 0 &&
    variants.every((v) => v.label.trim() && Number(v.price) > 0 && v.sku.trim()) &&
    new Set(variants.map((v) => v.label.trim())).size === variants.length);

  const create = useAction(() => api.createProduct({
    supplierId: form.supplierId, sectionId: form.sectionId, name: form.name.trim(), unit: form.unit.trim(),
    ...(hasVariants
      ? { variants: variants.map((v) => ({ label: v.label.trim(), price: Number(v.price), stockQty: Number(v.stockQty) || 0,
          sku: v.sku.trim() || undefined, imageUrl: v.imageUrl || undefined })) }
      : { basePrice: Number(form.basePrice), stockQty: Number(form.stockQty) || 0 }),
    supplierSku: hasVariants ? undefined : (form.supplierSku.trim() || undefined),
    imageUrl: hasVariants ? undefined : (imageUrl || undefined),
  }));

  const valid = form.supplierId && form.sectionId && form.name.trim() && form.unit.trim() && variantsValid &&
    (hasVariants || (Number(form.basePrice) > 0 && form.supplierSku.trim()));
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadError(""); setUploading(true);
    api.uploadImage(file)
      .then((res) => setImageUrl(res.url))
      .catch(() => setUploadError("تعذّر رفع الصورة"))
      .finally(() => setUploading(false));
  }

  // بعد إنشاء الصنف الأساسي، نعرض إدارة الأنواع مباشرة عشان يضيف الألوان/المقاسات لو يحتاج
  if (createdProduct) {
    return (
      <div className="detail-card voucher-form" style={{ marginBottom: 16 }}>
        <p className="hint">تم إنشاء «{createdProduct.name}» بنجاح. تقدر تضيفله أنواع (ألوان/مقاسات/عبوات) الحين أو لاحقًا من إدارة الأصناف.</p>
        <AdminVariantsManager product={createdProduct} />
        <div className="add-form-actions" style={{ marginTop: 10 }}>
          <button className="btn-primary" onClick={() => onCreated()}>تم</button>
        </div>
      </div>
    );
  }

  return (
    <div className="detail-card voucher-form" style={{ marginBottom: 16 }}>
      <h2 className="subsection-heading">صنف جديد</h2>

      <label className="field-label">المورد</label>
      <select className="field-input" value={form.supplierId}
        onChange={(e) => setForm((f) => ({ ...f, supplierId: e.target.value, sectionId: "" }))}>
        <option value="">اختر المورد</option>
        {(suppliers.data ?? []).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
      </select>

      <label className="field-label">القسم</label>
      <select className="field-input" value={form.sectionId} onChange={set("sectionId")}>
        <option value="">{form.supplierId ? "اختر القسم" : "اختر المورد أولًا"}</option>
        {(sections.data ?? []).map((s) => {
          const parent = s.parent_id ? (sections.data ?? []).find((x) => x.id === s.parent_id) : null;
          return <option key={s.id} value={s.id}>{parent ? `${parent.name} ← ${s.name}` : s.name}</option>;
        })}
      </select>
      {form.supplierId && sections.data && !sections.data.length && (
        <p className="hint">ما فيش أقسام مخصصة لهذا المورد — خصّصها من صفحة المورد أولًا.</p>
      )}

      <label className="field-label">اسم الصنف</label>
      <input className="field-input" value={form.name} onChange={set("name")} />

      <label className="field-label">وحدة البيع</label>
      <input className="field-input" value={form.unit} onChange={set("unit")} placeholder="مثال: كرتونة، كيلو، قطعة" />

      <label style={{ display: "flex", alignItems: "center", gap: 8, margin: "8px 0 12px" }}>
        <input type="checkbox" checked={hasVariants} onChange={(e) => setHasVariants(e.target.checked)} />
        <span>الصنف له ألوان أو مقاسات أو عبوات مختلفة</span>
      </label>

      {hasVariants ? (
        <VariantsBuilder value={variants} onChange={setVariants} />
      ) : (
        <>
          <label className="field-label">السعر (د.ل)</label>
          <input className="field-input" type="number" min="0" step="0.05" value={form.basePrice} onChange={set("basePrice")} />

          <label className="field-label">الكمية المتوفرة</label>
          <input className="field-input" type="number" min="0" value={form.stockQty} onChange={set("stockQty")} />
        </>
      )}

      {hasVariants ? (
        <p className="hint">كود وصورة كل نوع تضيفهم داخل النوع نفسه، وصورة أول نوع تصير صورة الصنف للعميل.</p>
      ) : (
        <>
      <label className="field-label">رقم الصنف عند المورد (إجباري)</label>
      <input className="field-input" value={form.supplierSku} onChange={set("supplierSku")} />

      <label className="field-label">صورة الصنف (اختياري)</label>
      {imageUrl ? (
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
          <img src={imageUrl} alt="" style={{ width: 56, height: 56, objectFit: "cover", borderRadius: 8 }} />
          <button className="link-btn" onClick={() => setImageUrl("")}>إزالة الصورة</button>
        </div>
      ) : (
        <button type="button" className="btn-ghost" style={{ maxWidth: 200, marginBottom: 12 }} disabled={uploading}
          onClick={() => fileRef.current?.click()}>
          {uploading ? "جارٍ الرفع…" : "رفع صورة"}
        </button>
      )}
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
        </>
      )}
      {uploadError && <p className="field-error">{uploadError}</p>}

      {create.error && <p className="field-error">{create.error}</p>}
      <div className="add-form-actions">
        <button className="btn-primary" disabled={!valid || uploading || create.pending}
          onClick={() => create.run().then((p) => (hasVariants ? onCreated() : setCreatedProduct(p))).catch(() => {})}>
          {create.pending ? "جارٍ الحفظ…" : "حفظ الصنف"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

function SettingsView({ can }) {
  const [tab, setTab] = useState("sections");
  return (
    <div className="screen">
      <div className="chip-row">
        <button className={"chip" + (tab === "sections" ? " chip-active" : "")} onClick={() => setTab("sections")}>الأقسام</button>
        <button className={"chip" + (tab === "zones" ? " chip-active" : "")} onClick={() => setTab("zones")}>مناطق التوصيل</button>
        <button className={"chip" + (tab === "vehicles" ? " chip-active" : "")} onClick={() => setTab("vehicles")}>أنواع السيارات</button>
        <button className={"chip" + (tab === "banners" ? " chip-active" : "")} onClick={() => setTab("banners")}>البانرات الترويجية</button>
      </div>
      {tab === "sections" && <SectionsSettings can={can} />}
      {tab === "zones" && <ZonesSettings can={can} />}
      {tab === "vehicles" && <VehicleTypesSettings can={can} />}
      {tab === "banners" && <BannersSettings can={can} />}
    </div>
  );
}

function PendingProductsSettings({ onChanged }) {
  const { data, loading, error, reload } = useFetch(() => api.products({ approvalStatus: "pending" }), []);
  const refresh = () => { reload(); onChanged?.(); };

  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;

  return (
    <div>
      <p className="hint">أصناف أضافها الموردين وما زالت بانتظار موافقتك — لن تظهر للعميل قبل الموافقة عليها.</p>
      {!data?.length ? (
        <div className="center-state"><p>لا توجد أصناف بانتظار الموافقة حاليًا</p></div>
      ) : (
        <table className="data-table">
          <thead><tr><th>صورة</th><th>الصنف</th><th>المورد</th><th>القسم</th><th>السعر</th><th></th></tr></thead>
          <tbody>
            {data.map((p) => <PendingProductRow key={p.id} product={p} onDone={refresh} />)}
          </tbody>
        </table>
      )}
    </div>
  );
}

function PendingProductRow({ product: p, onDone }) {
  const [rejecting, setRejecting] = useState(false);
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState("");
  const decide = useAction((status, noteVal) => api.approveProduct(p.id, { status, note: noteVal || undefined }));
  const { data: variants, loading: vLoading, error: vError, reload: reloadVariants } = useFetch(() => api.productVariants(p.id), [p.id]);
  const vList = variants || [];
  const totalQty = vList.filter((v) => v.is_active).reduce((s, v) => s + Number(v.stock_qty || 0), 0);

  return (
    <>
      <tr>
        <td>
          {p.image_url
            ? <img src={p.image_url} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }} />
            : <div style={{ width: 40, height: 40, borderRadius: 8, background: "var(--paper)", display: "flex",
                alignItems: "center", justifyContent: "center", color: "var(--ink-soft)" }}><ImageIcon size={16} /></div>}
        </td>
        <td className="cell-id">
          {p.name} <span className="cell-muted">({p.unit})</span>
          {vList.length > 0 && <div className="cell-muted" style={{ fontSize: 12 }}>{vList.length} أنواع — إجمالي الكمية {totalQty}</div>}
        </td>
        <td className="cell-muted">{p.supplier_name}</td>
        <td className="cell-muted">{p.section_name}</td>
        <td>{money(p.base_price)}</td>
        <td style={{ display: "flex", gap: 6, flexWrap: "wrap", minWidth: 220 }}>
          {rejecting ? (
            <>
              <input className="field-input" style={{ maxWidth: 180 }} placeholder="سبب الرفض (اختياري)"
                value={note} onChange={(e) => setNote(e.target.value)} />
              <button className="invoice-action-btn" disabled={decide.pending}
                onClick={() => decide.run("rejected", note).then(onDone).catch(() => {})}>تأكيد الرفض</button>
              <button className="btn-ghost" onClick={() => setRejecting(false)}>تراجع</button>
            </>
          ) : (
            <>
              <button className="invoice-action-btn" onClick={() => setOpen((o) => !o)}>{open ? "إغلاق المراجعة" : "مراجعة وتعديل"}</button>
              <button className="invoice-action-btn" disabled={decide.pending}
                onClick={() => decide.run("approved").then(onDone).catch(() => {})}>موافقة</button>
              <button className="invoice-action-btn" onClick={() => setRejecting(true)}>رفض</button>
            </>
          )}
          {decide.error && <p className="field-error">{decide.error}</p>}
        </td>
      </tr>
      {open && (
        <tr>
          <td colSpan={6} style={{ background: "var(--paper)", padding: 12 }}>
            <PendingProductEditor product={p} onSaved={onDone} />
            <h3 className="subsection-heading" style={{ marginTop: 14 }}>الأنواع</h3>
            {vLoading ? <Spinner /> : vError ? <ErrorState message={vError} onRetry={reloadVariants} /> : (
              !vList.length ? <p className="cell-muted">هذا الصنف بدون أنواع</p> : (
                vList.map((v) => <PendingVariantEditor key={v.id} variant={v} onDone={reloadVariants} />)
              )
            )}
            <p className="hint" style={{ marginTop: 8 }}>عدّل أي حاجة واضغط «حفظ» على كل سطر، وبعدها اضغط «موافقة».</p>
          </td>
        </tr>
      )}
    </>
  );
}

// تعديل بيانات الصنف نفسه (الاسم/السعر/الصورة) قبل الموافقة
function PendingProductEditor({ product: p, onSaved }) {
  const [name, setName] = useState(p.name);
  const [price, setPrice] = useState(p.base_price);
  const [imageUrl, setImageUrl] = useState(p.image_url || "");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);
  const save = useAction(() => api.updateProduct(p.id, {
    name: name.trim(), basePrice: Number(price), imageUrl: imageUrl || undefined,
  }));
  const dirty = name.trim() !== p.name || Number(price) !== Number(p.base_price) || (imageUrl || "") !== (p.image_url || "");
  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    api.uploadImage(file).then((res) => setImageUrl(res.url)).catch(() => {}).finally(() => setUploading(false));
  }
  return (
    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end" }}>
      <div style={{ flex: "2 1 160px" }}>
        <label className="field-label">اسم الصنف</label>
        <input className="field-input" style={{ marginBottom: 0 }} value={name} onChange={(e) => setName(e.target.value)} />
      </div>
      <div style={{ flex: "1 1 100px" }}>
        <label className="field-label">السعر الأساسي</label>
        <input className="field-input" style={{ marginBottom: 0 }} type="number" min="0" step="0.05" value={price} onChange={(e) => setPrice(e.target.value)} />
      </div>
      <div>
        <label className="field-label">الصورة</label>
        <button type="button" className="btn-ghost" style={{ width: "auto", padding: 4 }} disabled={uploading} onClick={() => fileRef.current?.click()}>
          {uploading ? "…" : imageUrl
            ? <img src={imageUrl} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8, display: "block" }} />
            : "📷 صورة"}
        </button>
        <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
      </div>
      {dirty && (
        <button className="invoice-action-btn" disabled={save.pending || uploading || !name.trim() || !(Number(price) > 0)}
          onClick={() => save.run().then(onSaved).catch(() => {})}>
          {save.pending ? "…" : "حفظ الصنف"}
        </button>
      )}
      {save.error && <p className="field-error" style={{ width: "100%" }}>{save.error}</p>}
    </div>
  );
}

// تعديل نوع واحد (الاسم/السعر/الكمية/الكود/الصورة) قبل الموافقة
function PendingVariantEditor({ variant: v, onDone }) {
  const [label, setLabel] = useState(v.label);
  const [price, setPrice] = useState(v.price);
  const [stockQty, setStockQty] = useState(v.stock_qty);
  const [sku, setSku] = useState(v.sku || "");
  const [imageUrl, setImageUrl] = useState(v.image_url || "");
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);
  const save = useAction(() => api.updateProductVariant(v.id, {
    label: label.trim(), price: Number(price), stockQty: Number(stockQty) || 0,
    sku: sku.trim() || undefined, imageUrl: imageUrl || undefined,
  }));
  const remove = useAction(() => api.deleteProductVariant(v.id));
  const dirty = label.trim() !== v.label || Number(price) !== Number(v.price) || Number(stockQty) !== Number(v.stock_qty)
    || sku.trim() !== (v.sku || "") || (imageUrl || "") !== (v.image_url || "");
  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    api.uploadImage(file).then((res) => setImageUrl(res.url)).catch(() => {}).finally(() => setUploading(false));
  }
  return (
    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "flex-end", padding: "8px 0", borderTop: "1px solid var(--line, #e5e5e5)" }}>
      <div>
        <button type="button" className="btn-ghost" style={{ width: "auto", padding: 4 }} disabled={uploading} onClick={() => fileRef.current?.click()}>
          {uploading ? "…" : imageUrl
            ? <img src={imageUrl} alt="" style={{ width: 44, height: 44, objectFit: "cover", borderRadius: 8, display: "block" }} />
            : "📷"}
        </button>
        <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
      </div>
      <div style={{ flex: "2 1 140px" }}>
        <label className="field-label">اسم النوع</label>
        <input className="field-input" style={{ marginBottom: 0 }} value={label} onChange={(e) => setLabel(e.target.value)} />
      </div>
      <div style={{ flex: "1 1 80px" }}>
        <label className="field-label">السعر</label>
        <input className="field-input" style={{ marginBottom: 0 }} type="number" min="0" step="0.05" value={price} onChange={(e) => setPrice(e.target.value)} />
      </div>
      <div style={{ flex: "1 1 70px" }}>
        <label className="field-label">الكمية</label>
        <input className="field-input" style={{ marginBottom: 0 }} type="number" min="0" value={stockQty} onChange={(e) => setStockQty(e.target.value)} />
      </div>
      <div style={{ flex: "1 1 90px" }}>
        <label className="field-label">الكود</label>
        <input className="field-input" style={{ marginBottom: 0 }} dir="ltr" value={sku} onChange={(e) => setSku(e.target.value)} />
      </div>
      {dirty && (
        <button className="invoice-action-btn" disabled={save.pending || uploading || !label.trim() || !(Number(price) > 0)}
          onClick={() => save.run().then(onDone).catch(() => {})}>
          {save.pending ? "…" : "حفظ"}
        </button>
      )}
      <button className="invoice-action-btn" disabled={remove.pending}
        onClick={() => { if (window.confirm(`حذف النوع "${v.label}"؟`)) remove.run().then(onDone).catch(() => {}); }}>حذف</button>
      {(save.error || remove.error) && <p className="field-error" style={{ width: "100%" }}>{save.error || remove.error}</p>}
    </div>
  );
}

function BannersSettings({ can }) {
  const { data, loading, error, reload } = useFetch(() => api.adminBanners(), []);
  const [showAdd, setShowAdd] = useState(false);
  const secs = useFetch(() => api.sections(), []);
  const mainSections = (Array.isArray(secs.data) ? secs.data : []).filter((s) => !s.parent_id && s.is_active !== false);

  return (
    <div>
      <p className="hint">
        البانرات اللي "مفعّلة" بس تظهر بالشاشة الرئيسية لتطبيق العميل، بالترتيب المحدد (الأصغر أول).
        لو فيها أكتر من بانر مفعّل، تتناوب تلقائيًا كل بضع ثواني.
        البانر يظهر بس للعملاء اللي مفعّلين عندهم الأقسام المحددة له، والبانرات العامة (لكل الأقسام) تظهر للجميع.
      </p>
      {loading ? <Spinner /> : error ? <ErrorState message={error} onRetry={reload} /> : (
        <div className="ledger-list" style={{ marginBottom: 16 }}>
          {(data ?? []).map((b) => <BannerRow key={b.id} banner={b} can={can} onChanged={reload} mainSections={mainSections} />)}
          {!data?.length && <Empty icon={ImageIcon} text="لا توجد بانرات بعد" />}
        </div>
      )}
      {can("catalog.manage") && (
        showAdd
          ? <AddBannerForm mainSections={mainSections} onClose={() => setShowAdd(false)} onCreated={() => { setShowAdd(false); reload(); }} />
          : <button className="btn-primary" style={{ maxWidth: 220 }} onClick={() => setShowAdd(true)}>
              <Plus size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} /> إضافة بانر جديد
            </button>
      )}
    </div>
  );
}

// اختيار الأقسام الرئيسية المستهدفة للبانر — فارغ = عام (لكل الأقسام)
function BannerSectionPicker({ mainSections, value, onChange }) {
  const general = value.length === 0;
  const toggleOne = (id) => onChange(value.includes(id) ? value.filter((x) => x !== id) : [...value, id]);
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 12 }}>
      <button type="button" className={"chip" + (general ? " chip-active" : "")} onClick={() => onChange([])}>
        كل الأقسام
      </button>
      {mainSections.map((s) => (
        <button type="button" key={s.id} className={"chip" + (value.includes(s.id) ? " chip-active" : "")}
          onClick={() => toggleOne(s.id)}>
          {s.name}
        </button>
      ))}
    </div>
  );
}

function BannerRow({ banner, can, onChanged, mainSections }) {
  const toggle = useAction(() => api.updateBanner(banner.id, { isActive: !banner.is_active }));
  const remove = useAction(() => api.deleteBanner(banner.id));
  const [confirming, setConfirming] = useState(false);
  const [editingSections, setEditingSections] = useState(false);
  const [draftIds, setDraftIds] = useState([]);
  const saveSections = useAction(() => api.updateBanner(banner.id, { sectionIds: draftIds }));
  const names = Array.isArray(banner.section_names) ? banner.section_names : [];

  return (
    <div className="ledger-row" style={{ cursor: "default", flexWrap: "wrap" }}>
      <img src={banner.image_url} alt="" style={{ width: 64, height: 40, objectFit: "cover", borderRadius: 8, flex: "none" }} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div className="ledger-row-title" style={{ fontSize: 14 }}>{banner.title || "بدون عنوان"}</div>
        <span className="cell-muted">ترتيب: {banner.sort_order}{banner.link_url ? " · له رابط" : ""}</span>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 4, marginTop: 4 }}>
          {names.length
            ? names.map((n, i) => <span key={i} className="status-pill status-pill-approved">{n}</span>)
            : <span className="status-pill">عام — لكل الأقسام</span>}
        </div>
      </div>
      {can("catalog.manage") && (
        <div style={{ display: "flex", gap: 6, flex: "none", flexWrap: "wrap" }}>
          <button className="invoice-action-btn"
            onClick={() => { setDraftIds(Array.isArray(banner.section_ids) ? banner.section_ids : []); setEditingSections((v) => !v); }}>
            تعديل الأقسام
          </button>
          <button className="invoice-action-btn" disabled={toggle.pending}
            onClick={() => toggle.run().then(onChanged).catch(() => {})}>
            {banner.is_active ? "إخفاء" : "تفعيل"}
          </button>
          {confirming ? (
            <button className="invoice-action-btn" disabled={remove.pending}
              onClick={() => remove.run().then(onChanged).catch(() => {})}>تأكيد الحذف</button>
          ) : (
            <button className="invoice-action-btn" onClick={() => setConfirming(true)}>حذف</button>
          )}
        </div>
      )}
      {editingSections && can("catalog.manage") && (
        <div style={{ width: "100%", paddingTop: 8 }}>
          <label className="field-label">الأقسام المستهدفة</label>
          <BannerSectionPicker mainSections={mainSections} value={draftIds} onChange={setDraftIds} />
          {saveSections.error && <p className="field-error">{saveSections.error}</p>}
          <div className="add-form-actions">
            <button className="btn-primary" disabled={saveSections.pending}
              onClick={() => saveSections.run().then(() => { setEditingSections(false); onChanged(); }).catch(() => {})}>
              {saveSections.pending ? "جارٍ الحفظ…" : "حفظ الأقسام"}
            </button>
            <button className="btn-ghost" onClick={() => setEditingSections(false)}>إلغاء</button>
          </div>
        </div>
      )}
    </div>
  );
}

function AddBannerForm({ onClose, onCreated, mainSections }) {
  const [sectionIds, setSectionIds] = useState([]);
  const [imageUrl, setImageUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const [title, setTitle] = useState("");
  const [subtitle, setSubtitle] = useState("");
  const [linkUrl, setLinkUrl] = useState("");
  const [sortOrder, setSortOrder] = useState("0");
  const fileRef = useRef(null);

  const create = useAction(() => api.createBanner({
    imageUrl, title: title.trim() || undefined, subtitle: subtitle.trim() || undefined,
    linkUrl: linkUrl.trim() || undefined, sortOrder: Number(sortOrder) || 0,
    sectionIds,
  }));

  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadError(""); setUploading(true);
    api.uploadImage(file)
      .then((res) => setImageUrl(res.url))
      .catch((err) => setUploadError(err?.message || "تعذّر رفع الصورة — حاول مرة أخرى"))
      .finally(() => setUploading(false));
  }

  return (
    <div className="detail-card voucher-form" style={{ marginTop: 12 }}>
      <label className="field-label">صورة البانر</label>
      {imageUrl ? (
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
          <img src={imageUrl} alt="" style={{ width: 120, height: 60, objectFit: "cover", borderRadius: 8 }} />
          <button className="link-btn" onClick={() => setImageUrl("")}>إزالة الصورة</button>
        </div>
      ) : (
        <button type="button" className="btn-ghost" style={{ maxWidth: 220, marginBottom: 12 }} disabled={uploading}
          onClick={() => fileRef.current?.click()}>
          <ImageIcon size={16} style={{ verticalAlign: "-3px", marginLeft: 6 }} />
          {uploading ? "جارٍ الرفع…" : "رفع صورة"}
        </button>
      )}
      <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
      {uploadError && <p className="field-error">{uploadError}</p>}

      <label className="field-label">العنوان (اختياري)</label>
      <input className="field-input" value={title} onChange={(e) => setTitle(e.target.value)} />

      <label className="field-label">النص الفرعي (اختياري)</label>
      <input className="field-input" value={subtitle} onChange={(e) => setSubtitle(e.target.value)} />

      <label className="field-label">رابط عند الضغط (اختياري)</label>
      <input className="field-input" placeholder="https://..." value={linkUrl} onChange={(e) => setLinkUrl(e.target.value)} />

      <label className="field-label">ترتيب الظهور (الأصغر أول)</label>
      <input className="field-input" type="number" value={sortOrder} onChange={(e) => setSortOrder(e.target.value)} />

      <label className="field-label">الأقسام المستهدفة (الافتراضي: كل الأقسام)</label>
      <BannerSectionPicker mainSections={mainSections} value={sectionIds} onChange={setSectionIds} />

      {create.error && <p className="field-error">{create.error}</p>}
      <div className="add-form-actions">
        <button className="btn-primary" disabled={!imageUrl || uploading || create.pending}
          onClick={() => create.run().then(onCreated).catch(() => {})}>
          {create.pending ? "جارٍ الحفظ…" : "إضافة البانر"}
        </button>
        <button className="btn-ghost" onClick={onClose}>إلغاء</button>
      </div>
    </div>
  );
}

function SectionsSettings({ can }) {
  const { data, loading, error, reload } = useFetch(() => api.sections(), []);
  const [showAdd, setShowAdd] = useState(false);
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [imageUrl, setImageUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const fileRef = useRef(null);
  const create = useAction(() => api.createSection({
    name: name.trim(), imageUrl: imageUrl || undefined,
  }));
  const [openSubsectionsFor, setOpenSubsectionsFor] = useState(null); // section id مفتوح حاليًا

  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadError(""); setUploading(true);
    api.uploadImage(file)
      .then((res) => setImageUrl(res.url))
      .catch((err) => setUploadError(err?.message || "تعذّر رفع الصورة — حاول مرة أخرى"))
      .finally(() => setUploading(false));
  }

  if (loading) return <Spinner />;
  if (error) return <ErrorState message={error} onRetry={reload} />;

  return (
    <>
      {can("accounts.sections") && (
        showAdd ? (
          <div className="detail-card voucher-form">
            <h2 className="subsection-heading">قسم جديد</h2>
            <label className="field-label">اسم القسم</label>
            <input className="field-input" value={name} onChange={(e) => setName(e.target.value)} placeholder="مثال: القرطاسية" />

            <label className="field-label">صورة القسم (اختياري)</label>
            {imageUrl ? (
              <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
                <img src={imageUrl} alt="" style={{ width: 56, height: 56, objectFit: "cover", borderRadius: 8 }} />
                <button className="link-btn" onClick={() => setImageUrl("")}>إزالة الصورة</button>
              </div>
            ) : (
              <button type="button" className="btn-ghost" style={{ maxWidth: 200, marginBottom: 12 }} disabled={uploading}
                onClick={() => fileRef.current?.click()}>
                {uploading ? "جارٍ الرفع…" : "رفع صورة"}
              </button>
            )}
            <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" style={{ display: "none" }} onChange={handleFile} />
            {uploadError && <p className="field-error">{uploadError}</p>}

            {create.error && <p className="field-error">{create.error}</p>}
            <div className="add-form-actions">
              <button className="btn-primary" disabled={!name.trim() || uploading || create.pending}
                onClick={() => create.run().then(() => { reload(); setShowAdd(false); setName(""); setSlug(""); setImageUrl(""); }).catch(() => {})}>
                {create.pending ? "جارٍ الحفظ…" : "حفظ القسم"}
              </button>
              <button className="btn-ghost" onClick={() => setShowAdd(false)}>إلغاء</button>
            </div>
          </div>
        ) : (
          <button className="chip chip-add" style={{ marginBottom: 16 }} onClick={() => setShowAdd(true)}>
            <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> إضافة قسم جديد
          </button>
        )
      )}
      <table className="data-table">
        <thead><tr><th>صورة</th><th>القسم</th><th>المعرّف</th><th>الحالة</th><th></th></tr></thead>
        <tbody>
          {(data ?? []).map((s) => (
            <React.Fragment key={s.id}>
              <SectionRow section={s} can={can} onDone={reload}
                isOpen={openSubsectionsFor === s.id}
                onToggleSubsections={() => setOpenSubsectionsFor((cur) => (cur === s.id ? null : s.id))} />
              {openSubsectionsFor === s.id && (
                <tr>
                  <td colSpan={5} style={{ background: "var(--paper)" }}>
                    <SubsectionsManager parent={s} can={can} />
                  </td>
                </tr>
              )}
            </React.Fragment>
          ))}
        </tbody>
      </table>
    </>
  );
}

function SubsectionsManager({ parent, can }) {
  const { data, loading, error, reload } = useFetch((sig) => api.sections({ parentId: parent.id }, sig), [parent.id]);
  const [showAdd, setShowAdd] = useState(false);
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const create = useAction(() => api.createSection({
    name: name.trim(), parentId: parent.id,
  }));

  return (
    <div style={{ padding: "10px 8px" }}>
      <h3 className="subsection-heading" style={{ fontSize: 14, marginBottom: 8 }}>تصنيفات «{parent.name}» الفرعية</h3>
      {loading ? <Spinner /> : error ? <ErrorState message={error} onRetry={reload} /> : (
        <table className="data-table">
          <thead><tr><th>التصنيف الفرعي</th><th>المعرّف</th><th>الحالة</th><th></th></tr></thead>
          <tbody>
            {(data ?? []).map((s) => <SectionRow key={s.id} section={s} can={can} onDone={reload} compact />)}
            {!data?.length && <tr><td colSpan={4} className="cell-muted">لا توجد تصنيفات فرعية بعد</td></tr>}
          </tbody>
        </table>
      )}
      {can("accounts.sections") && (
        showAdd ? (
          <div className="detail-card voucher-form" style={{ marginTop: 10 }}>
            <label className="field-label">اسم التصنيف الفرعي</label>
            <input className="field-input" value={name} onChange={(e) => setName(e.target.value)} placeholder="مثال: معجنات" />
            {create.error && <p className="field-error">{create.error}</p>}
            <div className="add-form-actions">
              <button className="btn-primary" disabled={!name.trim() || create.pending}
                onClick={() => create.run().then(() => { reload(); setShowAdd(false); setName(""); setSlug(""); }).catch(() => {})}>
                {create.pending ? "جارٍ الحفظ…" : "حفظ"}
              </button>
              <button className="btn-ghost" onClick={() => setShowAdd(false)}>إلغاء</button>
            </div>
          </div>
        ) : (
          <button className="chip chip-add" style={{ marginTop: 8 }} onClick={() => setShowAdd(true)}>
            <Plus size={14} style={{ verticalAlign: "-2px", marginLeft: 4 }} /> إضافة تصنيف فرعي
          </button>
        )
      )}
    </div>
  );
}

function SectionRow({ section: s, can, onDone, isOpen, onToggleSubsections, compact }) {
  const toggle = useAction(() => api.updateSection(s.id, { isActive: !(s.is_active !== false) }));
  const uploadImg = useAction((url) => api.updateSection(s.id, { imageUrl: url }));
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);
  const [renaming, setRenaming] = useState(false);
  const [nameDraft, setNameDraft] = useState("");
  const rename = useAction(() => api.updateSection(s.id, { name: nameDraft.trim() }));

  function handleFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    api.uploadImage(file)
      .then((res) => uploadImg.run(res.url))
      .then(onDone)
      .catch(() => {})
      .finally(() => setUploading(false));
  }

  return (
    <tr>
      <td>
        {s.image_url
          ? <img src={s.image_url} alt="" style={{ width: 40, height: 40, objectFit: "cover", borderRadius: 8 }} />
          : <div style={{ width: 40, height: 40, borderRadius: 8, background: "var(--paper)", display: "flex",
              alignItems: "center", justifyContent: "center", color: "var(--ink-soft)" }}><ImageIcon size={16} /></div>}
      </td>
      <td className="cell-id" style={compact ? { paddingRight: 20 } : undefined}>
        {renaming ? (
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
            <input className="field-input" style={{ marginBottom: 0, maxWidth: 200 }} value={nameDraft}
              onChange={(e) => setNameDraft(e.target.value)} />
            <button className="invoice-action-btn" disabled={nameDraft.trim().length < 2 || rename.pending}
              onClick={() => rename.run().then(() => { setRenaming(false); onDone(); }).catch(() => {})}>حفظ</button>
            <button className="invoice-action-btn" onClick={() => setRenaming(false)}>إلغاء</button>
            {rename.error && <span className="field-error" style={{ width: "100%" }}>{rename.error}</span>}
          </div>
        ) : (<>{compact ? "— " : ""}{s.name}</>)}
      </td>
      <td className="cell-muted" dir="ltr">{s.slug}</td>
      <td><span className={"status-pill" + (s.is_active !== false ? " status-pill-approved" : "")}>
        {s.is_active !== false ? "مفعّل" : "موقوف"}</span></td>
      <td style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
        {!compact && onToggleSubsections && (
          <button className="invoice-action-btn" onClick={onToggleSubsections}>
            {isOpen ? "إخفاء التصنيفات الفرعية" : "التصنيفات الفرعية"}
          </button>
        )}
        {can("accounts.sections") && (
          <button className="invoice-action-btn" disabled={toggle.pending}
            onClick={() => toggle.run().then(onDone).catch(() => {})}>
            {s.is_active !== false ? "إيقاف" : "تفعيل"}
          </button>
        )}
        {can("accounts.sections") && !renaming && (
          <button className="invoice-action-btn" onClick={() => { setNameDraft(s.name || ""); setRenaming(true); }}>
            تعديل الاسم
          </button>
        )}
        {can("catalog.manage") && (
          <>
            <button className="invoice-action-btn" disabled={uploading} onClick={() => fileRef.current?.click()}>
              {uploading ? "…" : "تغيير الصورة"}
            </button>
            <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp"
              style={{ display: "none" }} onChange={handleFile} />
          </>
        )}
      </td>
    </tr>
  );
}

