function SupportThreadPanel({ type, actorId, actorName, onBack }) {
  const { data, loading, error, reload } = useFetch(() => api.adminSupportThread(type, actorId), [type, actorId]);
  const [draft, setDraft] = useState("");
  const send = useAction(() => api.adminSendSupportMessage(type, actorId, draft.trim()));
  const messages = data?.messages ?? [];

  function submit() {
    if (!draft.trim()) return;
    send.run().then(() => { setDraft(""); reload(); }).catch(() => {});
  }

  return (
    <div>
      <button className="invoice-action-btn" style={{ marginBottom: 12 }} onClick={onBack}>
        <ArrowRight size={13} /> رجوع لقائمة المحادثات
      </button>
      <h3 style={{ margin: "0 0 10px" }}>{actorName}</h3>
      <div className="chat-panel">
        <div className="chat-thread">
          {loading ? <Spinner label="جارٍ التحميل…" />
           : error ? <ErrorState message={error} onRetry={reload} />
           : !messages.length ? <p className="chat-empty">لا توجد رسائل بعد.</p>
           : messages.map((m) => (
              <div className={"chat-bubble " + (m.sender_role === "admin" ? "chat-bubble-user" : "chat-bubble-support")} key={m.id}>
                <span>{m.body}</span>
                <span className="chat-time">{new Date(m.created_at).toLocaleTimeString("ar", { hour: "2-digit", minute: "2-digit" })}</span>
              </div>
            ))}
        </div>
        <div className="chat-input-row">
          <input className="chat-input" placeholder="اكتب ردًا..." value={draft}
            onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => e.key === "Enter" && submit()} />
          <button className="chat-send" onClick={submit} disabled={send.pending} aria-label="إرسال"><Send size={17} /></button>
        </div>
        {send.error && <p className="field-error">{send.error}</p>}
      </div>
    </div>
  );
}

